using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.CSharp;
using System.Text;

namespace Lurp.Workspace;

/// <summary>
///     The single combined generated-code predicate (D4, D167.1-2):
///     <see cref="GeneratedFilePaths.IsGenerated" /> for the file name, plus
///     Roslyn's exact leading-comment rule (<c>&lt;auto-generated</c> or
///     <c>&lt;autogenerated</c> in a single-line or multi-line comment before the
///     first token, compared ordinally with no byte cap).
/// </summary>
internal static class GeneratedCode
{
    public static bool IsGenerated(string? path, ReadOnlySpan<byte> utf8Bytes)
    {
        if (GeneratedFilePaths.IsGenerated(path))
            return true;

        return HasAutoGeneratedComment(utf8Bytes);
    }

    public static bool IsGenerated(SyntaxTree? tree)
    {
        if (tree == null)
            return false;

        if (GeneratedFilePaths.IsGenerated(tree.FilePath))
            return true;

        return HasAutoGeneratedComment(tree.GetRoot().GetLeadingTrivia());
    }

    public static bool HasAutoGeneratedComment(ReadOnlySpan<byte> utf8Bytes)
    {
        if (utf8Bytes.IsEmpty)
            return false;

        var text = Encoding.UTF8.GetString(utf8Bytes);
        return HasAutoGeneratedComment(SyntaxFactory.ParseLeadingTrivia(text));
    }

    /// <summary>
    ///     Returns the text following the <c>&lt;auto-generated</c> or
    ///     <c>&lt;autogenerated</c> marker inside the first matching leading
    ///     single-line or multi-line comment (with a trailing <c>*/</c> stripped for
    ///     multi-line comments), using Roslyn's exact ordinal rule with no byte cap,
    ///     or <see langword="null" /> when no such comment precedes the first token.
    /// </summary>
    public static string? TryGetAutoGeneratedCommentTail(SyntaxTriviaList leadingTrivia)
    {
        foreach (var trivia in leadingTrivia)
        {
            if (trivia.IsKind(SyntaxKind.SingleLineCommentTrivia))
            {
                if (TrySliceAfterMarker(trivia.ToString(), out var tail))
                    return tail;
            }
            else if (trivia.IsKind(SyntaxKind.MultiLineCommentTrivia))
            {
                var text = trivia.ToString();
                if (text.EndsWith("*/", StringComparison.Ordinal))
                    text = text[..^2];
                if (TrySliceAfterMarker(text, out var tail))
                    return tail;
            }
        }

        return null;
    }

    private static bool HasAutoGeneratedComment(SyntaxTriviaList leadingTrivia)
    {
        return TryGetAutoGeneratedCommentTail(leadingTrivia) != null;
    }

    private static bool TrySliceAfterMarker(string text, out string tail)
    {
        var index = text.IndexOf("<auto-generated", StringComparison.Ordinal);
        if (index >= 0)
        {
            tail = text[(index + "<auto-generated".Length)..];
            return true;
        }

        index = text.IndexOf("<autogenerated", StringComparison.Ordinal);
        if (index >= 0)
        {
            tail = text[(index + "<autogenerated".Length)..];
            return true;
        }

        tail = "";
        return false;
    }
}
